#include "mock_bq_bus.h"

#include <string.h>

typedef struct {
    uint8_t  is_write;
    uint8_t  reg;
    uint16_t len;
    int      ret;
    uint8_t  data[MOCK_BUS_MAX_DATA];   /* read: reply; write: expected bytes */
} MockXfer;

static MockXfer  s_xfers[MOCK_BUS_MAX_XFERS];
static uint32_t  s_xfer_count;
static uint32_t  s_xfer_next;

static int       s_ready_results[16];
static uint32_t  s_ready_count;
static uint32_t  s_ready_next;

static uint32_t  s_mismatches;
static uint32_t  s_unexpected;
static uint32_t  s_delay_total_ms;
static uint32_t  s_delay_calls;

void MockBus_Reset(void)
{
    memset(s_xfers, 0, sizeof(s_xfers));
    s_xfer_count = 0U;
    s_xfer_next  = 0U;

    memset(s_ready_results, 0, sizeof(s_ready_results));
    s_ready_count = 0U;
    s_ready_next  = 0U;

    s_mismatches     = 0U;
    s_unexpected     = 0U;
    s_delay_total_ms = 0U;
    s_delay_calls    = 0U;
}

void MockBus_ExpectRead(uint8_t reg, const uint8_t *data, uint16_t len, int ret)
{
    MockXfer *x;

    if (s_xfer_count >= MOCK_BUS_MAX_XFERS || len > MOCK_BUS_MAX_DATA) {
        return;   /* test scripting error; surfaces as unconsumed/unexpected */
    }
    x = &s_xfers[s_xfer_count++];
    x->is_write = 0U;
    x->reg      = reg;
    x->len      = len;
    x->ret      = ret;
    if (data != NULL) {
        memcpy(x->data, data, len);
    }
}

void MockBus_ExpectWrite(uint8_t reg, const uint8_t *expect, uint16_t len, int ret)
{
    MockXfer *x;

    if (s_xfer_count >= MOCK_BUS_MAX_XFERS || len > MOCK_BUS_MAX_DATA) {
        return;
    }
    x = &s_xfers[s_xfer_count++];
    x->is_write = 1U;
    x->reg      = reg;
    x->len      = len;
    x->ret      = ret;
    if (expect != NULL) {
        memcpy(x->data, expect, len);
    }
}

void MockBus_QueueReady(const int *results, uint32_t count)
{
    uint32_t i;

    s_ready_count = 0U;
    s_ready_next  = 0U;
    for (i = 0U; i < count && i < 16U; i++) {
        s_ready_results[s_ready_count++] = results[i];
    }
}

/* ---- BQ_Bus callbacks ---- */

static int mock_mem_read(void *ctx, uint8_t reg, uint8_t *data, uint16_t len)
{
    MockXfer *x;

    (void)ctx;

    if (s_xfer_next >= s_xfer_count) {
        s_unexpected++;
        return -1;
    }
    x = &s_xfers[s_xfer_next++];

    if (x->is_write != 0U || x->reg != reg || x->len != len) {
        s_mismatches++;
        return -1;
    }
    if (x->ret == 0 && data != NULL) {
        memcpy(data, x->data, len);
    }
    return x->ret;
}

static int mock_mem_write(void *ctx, uint8_t reg, const uint8_t *data, uint16_t len)
{
    MockXfer *x;

    (void)ctx;

    if (s_xfer_next >= s_xfer_count) {
        s_unexpected++;
        return -1;
    }
    x = &s_xfers[s_xfer_next++];

    if (x->is_write != 1U || x->reg != reg || x->len != len) {
        s_mismatches++;
        return -1;
    }
    if (data == NULL || memcmp(x->data, data, len) != 0) {
        s_mismatches++;
        return -1;
    }
    return x->ret;
}

static int mock_is_ready(void *ctx)
{
    (void)ctx;

    if (s_ready_next >= s_ready_count) {
        s_unexpected++;
        return -1;
    }
    return s_ready_results[s_ready_next++];
}

static void mock_delay_ms(void *ctx, uint32_t ms)
{
    (void)ctx;
    s_delay_total_ms += ms;
    s_delay_calls++;
}

static const BQ_Bus s_iface = {
    mock_mem_read,
    mock_mem_write,
    mock_is_ready,
    mock_delay_ms,
    NULL,
};

static const BQ_Bus s_iface_no_delay = {
    mock_mem_read,
    mock_mem_write,
    mock_is_ready,
    NULL,
    NULL,
};

const BQ_Bus *MockBus_Iface(void)        { return &s_iface; }
const BQ_Bus *MockBus_IfaceNoDelay(void) { return &s_iface_no_delay; }

/* ---- Verification helpers ---- */

uint32_t MockBus_Unconsumed(void)   { return s_xfer_count - s_xfer_next; }
uint32_t MockBus_Mismatches(void)   { return s_mismatches; }
uint32_t MockBus_Unexpected(void)   { return s_unexpected; }
uint32_t MockBus_DelayTotalMs(void) { return s_delay_total_ms; }
uint32_t MockBus_DelayCalls(void)   { return s_delay_calls; }
uint32_t MockBus_ReadyCalls(void)   { return s_ready_next; }
